      fuel_prices: { Row: FuelPriceRow; Insert: Partial<FuelPriceRow>; Update: Partial<FuelPriceRow>; Relationships: [] };
      fuel_price_submissions: { Row: FuelSubmissionRow; Insert: FuelSubmissionInsert; Update: Partial<FuelSubmissionRow>; Relationships: [] };
