      current_cement_rates: { Row: { id: string; brand_id: number; city_id: number; price_per_bag: number; effective_at: string; source_id: string }; Relationships: [] };
      current_steel_rates: { Row: { id: string; grade_id: number; city_id: number; price_per_maund: number; price_per_ton: number; effective_at: string; source_id: string }; Relationships: [] };
